import {VERSION,MISSIONS,HARDWARE,INSTRUMENTS,pick,clamp,preset,normalize,evaluate,start,advance,eventFor,EVENTS,result,forecast,deltaV} from './engine.js';
const $=s=>document.querySelector(s),esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(v,d=0)=>Number(v).toLocaleString('en-US',{maximumFractionDigits:d,minimumFractionDigits:d});
const KEY='apogee-v1';let storageOK=true,view='design',tab='spacecraft',mode='balanced',choice=null,forecastCache=null,toastTimer;
let state={design:preset(),run:null,archive:[],visited:false};
try{const raw=JSON.parse(localStorage.getItem(KEY)||'null');if(raw?.version===VERSION){state.design=normalize(raw.design);state.visited=!!raw.visited;state.archive=Array.isArray(raw.archive)?raw.archive.slice(0,12).filter(x=>x&&MISSIONS[x.mission]&&Number.isFinite(x.score)&&Number.isFinite(x.science)).map(x=>({...x,name:String(x.name).slice(0,48),design:normalize(x.design)})):[];if(raw.run?.design&&Array.isArray(raw.run.history)&&raw.run.history.length<=12){let s=start(normalize(raw.run.design));for(const h of raw.run.history)s=advance(s,h.mode,h.choice);state.run=s;if(s.phase==='operations')view='operations';}}}catch{storageOK=false;state={design:preset(),run:null,archive:[],visited:false};}
function save(){try{localStorage.setItem(KEY,JSON.stringify({version:VERSION,...state}));storageOK=true;}catch{storageOK=false;}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
const icon=(name)=>{const paths={arrow:'<path d="M4 8h9M9 4l4 4-4 4"/>',download:'<path d="M8 2v8M4 7l4 4 4-4M3 12v2h10v-2"/>',plus:'<path d="M8 3v10M3 8h10"/>',help:'<circle cx="8" cy="8" r="6"/><path d="M6.5 6a1.5 1.5 0 113 0c0 1-1.5 1-1.5 2M8 11v.2"/>',close:'<path d="M4 4l8 8M12 4l-8 8"/>',check:'<path d="M3 8l3 3 7-7"/>',archive:'<rect x="3" y="5" width="10" height="9" rx="1"/><path d="M2 2h12v3H2zM6 8h4"/>',upload:'<path d="M8 11V2M4 6l4-4 4 4M3 12v2h10v-2"/>'};return `<svg aria-hidden="true" width="16" height="16" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.3" stroke-linecap="round" stroke-linejoin="round">${paths[name]||paths.arrow}</svg>`;};
function top(){return `<header class="topbar"><div class="brand"><svg viewBox="0 0 50 50" aria-hidden="true"><circle cx="25" cy="25" r="14" fill="none" stroke="#214d45" stroke-width="1.4"/><ellipse cx="25" cy="25" rx="23" ry="9" transform="rotate(-40 25 25)" fill="none" stroke="#214d45" stroke-width="1.4"/><circle cx="42" cy="10" r="3.4" fill="#b48642"/></svg><div><strong>APOGEE</strong><small>MISSION DESIGN LAB</small></div></div><div class="topactions"><a class="btn desktop" href="./index.html">← Space exploration</a><span class="tag"><i></i>BROWSER MISSION SIMULATOR</span><button class="btn desktop" data-action="import">${icon('upload')} Import</button><button class="btn desktop" data-action="export">${icon('download')} Blueprint</button><button class="iconbtn" data-action="archive" aria-label="Open mission archive" title="Mission archive">${icon('archive')}</button><button class="iconbtn" data-action="guide" aria-label="Open flight handbook" title="Flight handbook">${icon('help')}</button></div></header><nav class="stagebar" aria-label="Mission stages"><div class="stages">${[['design','Design'],['review','Review'],['operations','Operate'],['debrief','Debrief']].map(([id,label],i)=>`${i?'<span class="stage-line" aria-hidden="true"></span>':''}<button class="stage ${view===id?'active':''}" data-view="${id}" ${(['operations','debrief'].includes(id)&&!state.run)||id==='debrief'&&state.run?.phase!=='complete'?'disabled':''} ${view===id?'aria-current="page"':''}><span>0${i+1}</span>${label}</button>`).join('')}</div><span class="version">LOCAL SAVE ${storageOK?'● ENABLED':'○ UNAVAILABLE'} &nbsp; / &nbsp; V1.0</span></nav>`;}
function footer(){return `<footer class="footer"><span>INDEPENDENT EDUCATIONAL GAME · CREATED FOR THE SPACE MISSION DESIGN CHALLENGE<br>NASA references inform the model. Hardware, costs and mission events are fictional.</span><span><button data-action="science">MODEL & SOURCES</button> &nbsp; / &nbsp; <button data-action="guide">FLIGHT HANDBOOK</button> &nbsp; / &nbsp; <button data-action="export">EXPORT</button><br>NO ACCOUNT REQUIRED · YOUR MISSIONS STAY ON THIS DEVICE</span></footer>`;}
function orbit(a,operating=false){const m=a.m,color=m.color;let surface=m.id==='earth'?`<path d="M216 108l-16 17-23 9-8 28 15 5 10 24 14-2 10 15 15-4 2-14-10-10 3-15 12-12-8-13 6-11zM260 151l15-17 23 2 8 15 20 5 7 22-15 17-13-9-17 3-6-13-17-6zM252 203l17 8 14 2 6 22-8 20-5 21-14 9-9-22 6-17-12-16zM305 117l20 9 8 13-20 7-19-9z" fill="#94bbaa" opacity=".85"/>`:`<g fill="${m.id==='mars'?'#b66646':'#757e80'}" opacity=".35"><circle cx="220" cy="152" r="26"/><circle cx="283" cy="208" r="31"/><circle cx="281" cy="129" r="13"/><circle cx="208" cy="221" r="11"/><circle cx="309" cy="175" r="9"/><path d="M201 192q34-47 69-15t60 20l-11 14q-40-23-70-8t-48-11"/></g>`;
return `<div class="orbit-panel" aria-label="Schematic spacecraft orbit around ${m.body}"><div class="orbit-top"><span class="sectionlabel">${operating?'LIVE MISSION':'ORBITAL PREVIEW'}</span><span class="live-pill"><i></i>${operating?'TELEMETRY':'DESIGN MODE'}</span></div><span class="orbit-note">SCHEMATIC · NOT TO SCALE</span><svg class="orbit-svg" viewBox="0 0 500 350" aria-hidden="true"><defs><radialGradient id="planet"><stop offset="0" stop-color="${color}"/><stop offset=".65" stop-color="${color}"/><stop offset="1" stop-color="#254349"/></radialGradient><radialGradient id="halo"><stop offset=".6" stop-color="${color}" stop-opacity=".16"/><stop offset="1" stop-color="${color}" stop-opacity="0"/></radialGradient><clipPath id="sphere"><circle cx="250" cy="186" r="87"/></clipPath><linearGradient id="shade"><stop offset="0" stop-color="#102e30" stop-opacity="0"/><stop offset=".6" stop-color="#102e30" stop-opacity=".08"/><stop offset="1" stop-color="#102e30" stop-opacity=".85"/></linearGradient></defs><circle cx="250" cy="186" r="123" fill="url(#halo)"/><path d="M48 186h404M250 65v244" stroke="#b3cabb" stroke-width=".5" opacity=".18"/><circle cx="250" cy="186" r="117" fill="none" stroke="#779891" stroke-width=".6" opacity=".2"/><ellipse cx="250" cy="186" rx="201" ry="87" transform="rotate(-${20+a.d.incl*.15} 250 186)" fill="none" stroke="#91b5a4" stroke-width="1" class="orbit-line" opacity=".65"/><circle cx="250" cy="186" r="87" fill="url(#planet)"/><g clip-path="url(#sphere)">${surface}<g stroke="#dae5d9" stroke-width=".6" fill="none" opacity=".18"><ellipse cx="250" cy="186" rx="38" ry="88"/><ellipse cx="250" cy="186" rx="69" ry="88"/><ellipse cx="250" cy="186" rx="89" ry="25"/><ellipse cx="250" cy="186" rx="89" ry="59"/></g><circle cx="250" cy="186" r="87" fill="url(#shade)"/></g><circle cx="250" cy="186" r="88" fill="none" stroke="#d6e5d5" stroke-width=".6" opacity=".35"/><path d="M51 254c38 49 154 49 257 7" stroke="#c4e0ad" fill="none" stroke-width="1.4"/><path d="M304 257l6 3-5 5" stroke="#c4e0ad" fill="none"/><g class="satellite"><path d="M378 105h-14l-15 29" stroke="#d7bd85" stroke-width=".8" opacity=".7"/><circle cx="384" cy="103" r="21" fill="#edbb76" opacity=".08"/><g transform="translate(384 103) rotate(-28)"><rect x="-10" y="-10" width="20" height="20" rx="2" fill="#dbb66d" stroke="#ffe5a9"/><rect x="-47" y="-8" width="33" height="17" rx="1" fill="#4c7182" stroke="#a8c4c7" stroke-width=".8"/><rect x="14" y="-8" width="33" height="17" rx="1" fill="#4c7182" stroke="#a8c4c7" stroke-width=".8"/><path d="M-36-8v17M-25-8v17M25-8v17M36-8v17M-47 0h33M14 0h33" stroke="#9eb3bb" stroke-width=".5"/><path d="M0-10v-12M-8-22q8 9 16 0" stroke="#e9e9cc" fill="none"/><path d="M-4 10l-3 7h14l-3-7" fill="#b0b6a7"/></g></g><text x="377" y="154" font-size="8" font-family="monospace" fill="#c4e0ad">${a.d.bus.toUpperCase()} / ${a.ins.length} INSTRUMENTS</text><text x="55" y="103" font-size="8" font-family="monospace" fill="#87a59b">${m.body.toUpperCase()} ORBIT</text><path d="M57 110h52l34 26" fill="none" stroke="#87a59b" stroke-width=".6" opacity=".5"/></svg><div class="orbit-bottom"><div><strong>${fmt(a.d.alt)} <span style="font-size:10px">km</span></strong><small>ORBIT ALTITUDE</small></div><div><strong>${fmt(a.period,1)} <span style="font-size:10px">min</span></strong><small>ORBITAL PERIOD</small></div><div><strong>${fmt(a.d.incl)}<span style="font-size:10px">°</span></strong><small>INCLINATION</small></div></div></div>`;}
function resource(label,value,max,unit,note,over=false,invert=false){const ratio=clamp(value/max*100,0,100);return `<div class="resource ${over?'over':''}"><div class="resource-top"><span>${label}</span><strong>${fmt(value,unit==='M$'?1:0)} <small>/ ${fmt(max)} ${unit==='M$'?'M$':unit}</small></strong></div><div class="track" role="meter" aria-label="${label}" aria-valuenow="${Math.round(value)}" aria-valuemin="0" aria-valuemax="${Math.max(max,Math.round(value))}"><i style="width:${ratio}%"></i></div><div class="resource-note ${!over&&invert?'positive':''}">${esc(note)}</div></div>`;}
function resources(a){const errors=a.issues.filter(x=>x.level==='error').length;return `<aside class="panel resources"><div class="panel-head"><h2>Engineering margins</h2><span class="sectionlabel">LIVE</span></div><div class="panel-body">${resource('Mission budget',a.cost,a.m.budget,'M$',`${a.reserve>=0?'$'+fmt(a.reserve,1)+'M contingency remaining':'Over budget'}`,a.reserve<0)}${resource('Launch mass',a.wet,a.capacity,'kg',`${fmt(a.capacity-a.wet)} kg ${a.capacity>=a.wet?'remaining':'over capacity'}`,a.wet>a.capacity)}${resource('Average power load',a.load,a.averageGeneration,'W',`${fmt(a.averageGeneration-a.load)} W net generation margin`,a.load>a.averageGeneration)}${resource('Maneuver requirement',a.requiredDV,a.dv,'m/s',`${fmt(a.dv-a.requiredDV)} m/s reserve capability`,a.dv<a.requiredDV)}<div class="review-status ${errors?'bad':''}"><strong>${errors?`${errors} launch blocker${errors>1?'s':''}`:'✓ Nominal design is feasible'}</strong><span>${errors?'Resolve blockers in design review.':`${a.issues.length} advisory flag${a.issues.length===1?'':'s'} · review before launch`}</span></div></div></aside>`;}
function missionMenu(a){return `<aside class="panel mission-left"><div class="panel-head"><h2>Choose your mission</h2></div><div class="mission-menu">${Object.values(MISSIONS).map(m=>`<button class="mission-option ${m.id===a.m.id?'selected':''}" data-mission="${m.id}" aria-pressed="${m.id===a.m.id}"><span class="planet-dot" style="background:${m.color}"></span><span><strong>${m.name}</strong><small>${m.body.toUpperCase()} ORBIT</small></span><em>↗</em></button>`).join('')}</div><div class="brief-card"><span class="sectionlabel">YOUR OBJECTIVE</span><h3>${a.m.objective}</h3><p>${a.m.pitch}</p><div class="brief-stats"><div><strong>${a.m.target}</strong><small>SCIENCE TARGET</small></div><div><strong>${a.m.turns*a.m.days}d</strong><small>OPERATIONS</small></div></div><button class="btn" data-action="brief">Read mission brief ${icon('arrow')}</button></div></aside>`;}
function component(kind,x,a){const selected=a.d[kind]===x.id;let specs=[`${x.mass||0} kg`,`$${x.cost}M`];if(kind==='launcher')specs=[`${x.caps[a.m.id]} kg`,'$'+x.cost+'M'];if(kind==='engine')specs.push(x.isp+' s Isp');if(kind==='power')specs.push(x.watts+' W @ 1 AU');if(kind==='bus')specs.push(x.slots+' slots');if(kind==='comm')specs.push(x.rates[a.m.id]+' Mb/turn');return `<button class="component ${selected?'selected':''}" data-kind="${kind}" data-component="${x.id}" aria-pressed="${selected}"><div class="component-top"><strong>${x.name}</strong><span class="check" aria-hidden="true">${selected?'✓':''}</span></div><p>${x.description}</p><div class="component-data">${specs.map(s=>`<span>${s}</span>`).join('')}</div></button>`;}
function field(key,title,value,unit,min,max,step,help){return `<div class="field"><label for="${key}">${title}<strong>${fmt(value)}${unit}</strong></label><input id="${key}" data-field="${key}" type="range" min="${min}" max="${max}" step="${step}" value="${value}" aria-valuetext="${value}${unit}"><small>${help}</small></div>`;}
function configuration(a){let content;if(tab==='spacecraft')content=`<div class="hardware-grid">${[['bus','01 / SPACECRAFT BUS'],['engine','02 / PROPULSION'],['power','03 / POWER SYSTEM'],['comm','04 / COMMUNICATIONS']].map(([k,name])=>`<section class="hardware-group"><h3>${name}</h3>${HARDWARE[k].map(x=>component(k,x,a)).join('')}</section>`).join('')}</div>`;if(tab==='payload')content=`<div class="hardware-grid">${INSTRUMENTS.map(x=>{const selected=a.d.payload.includes(x.id);return `<button class="component payload-card ${selected?'selected':''}" data-payload="${x.id}" aria-pressed="${selected}"><span class="sectionlabel">${x.type}${a.m.required.includes(x.id)?'<span class="required-chip">REQUIRED</span>':''}</span><div class="component-top"><strong>${x.name}</strong><span class="check" aria-hidden="true">${selected?'✓':''}</span></div><p>${x.description}</p><div class="component-data"><span>${x.mass} kg</span><span>$${x.cost}M</span><span>${x.power} W</span></div></button>`;}).join('')}</div><p class="subnote">${a.ins.length} / ${a.b.slots} slots used · ${a.payloadMass} / ${a.b.payload} kg payload · ${a.data.toFixed(1)} Mbit generated per nominal operations block</p>`;if(tab==='flight')content=`<div class="flight-grid"><section class="panel flight-fields">${field('alt','Circular orbit altitude',a.d.alt,' km',a.m.altMin,a.m.altMax,10,'Lower orbits improve modeled mapping detail. Orbital period and eclipse battery demand change with altitude.')}${field('incl','Orbit inclination',a.d.incl,'°',0,180,5,'A near-polar orbit covers more latitudes. This global mapping objective favors inclinations near 90°.')}${field('duty','Science duty cycle',a.d.duty,'%',25,100,5,'The fraction of time instruments are active. More observations demand more power and create more data.')}</section><section class="panel flight-fields">${field('fuel','Propellant loading',a.d.fuel,' kg',0,800,1,'Fuel improves maneuver capability but consumes mass and budget. The spacecraft must carry insertion, correction and retirement propellant.')}<div class="field"><label for="name">Mission callsign</label><input id="name" class="input" data-text="name" maxlength="48" value="${esc(a.d.name)}"><small>A name for the blueprint and your local mission archive.</small></div><div class="field"><label for="seed">Simulation seed</label><input id="seed" class="input" data-number="seed" type="number" min="1" max="999999" value="${a.d.seed}"><small>Same blueprint, seed and decisions produce the same outcome. Seeds vary observing conditions; events follow the same teaching sequence.</small></div></section></div>`;if(tab==='launch')content=`<div class="flight-grid"><div class="hardware-grid" style="grid-template-columns:1fr">${HARDWARE.launcher.map(x=>component('launcher',x,a)).join('')}</div><section class="panel panel-body"><span class="eyebrow">DELIVERY TO ${a.m.body.toUpperCase()}</span><h3>Injection matters.</h3><p class="subnote">The same launcher can carry far more mass to low Earth orbit than it can inject toward the Moon or Mars. The mass rating shown here is destination-specific.</p><table class="table"><tbody><tr><td>Selected destination</td><td>${a.m.body}</td></tr><tr><td>Wet spacecraft mass</td><td>${fmt(a.wet)} kg</td></tr><tr><td>Injection capacity</td><td>${fmt(a.capacity)} kg</td></tr><tr><td>Spacecraft insertion burn</td><td>${fmt(a.insertion)} m/s</td></tr></tbody></table><div class="notice">Launchers, capacities and costs are fictional. Atmospheric ascent and interplanetary transfer are abstracted; onboard burns use the ideal rocket equation.</div></section></div>`;
return `<section class="configuration"><div class="config-header"><h2>Build your spacecraft</h2><div class="config-tabs" role="group" aria-label="Design categories">${[['spacecraft','Spacecraft'],['payload','Instruments'],['flight','Flight plan'],['launch','Launch vehicle']].map(([id,name])=>`<button data-tab="${id}" class="${tab===id?'active':''}" aria-pressed="${tab===id}">${name}</button>`).join('')}</div></div>${content}</section>`;}
function design(){const a=evaluate(state.design);return `<div class="heading"><div><div class="eyebrow">THE MISSION STARTS WITH A TRADE-OFF</div><h1>Small decisions.<br>Extraordinary missions.</h1><p>Build with purpose. Balance your resources. Make every kilogram count.</p></div><button class="btn primary" data-view="review">Design review ${icon('arrow')}</button></div><div class="mission-grid">${missionMenu(a)}<section>${orbit(a)}<div class="orbit-data"><div class="mini-stat"><span class="sectionlabel">SCIENCE / BLOCK</span><strong>${fmt(a.science,1)} <span>pts</span></strong><small>Before observing conditions</small></div><div class="mini-stat"><span class="sectionlabel">DOWNLINK CAPACITY</span><strong>${fmt(a.downlink,1)} <span>Mb</span></strong><small>Nominal data per block</small></div><div class="mini-stat"><span class="sectionlabel">BATTERY / ECLIPSE</span><strong>${fmt(a.eclipseEnergy)} <span>Wh</span></strong><small>${fmt(a.b.battery*.8)} Wh usable storage</small></div></div></section>${resources(a)}</div>${configuration(a)}<div class="science-strip"><div><strong>The best spacecraft is the one that serves its mission.</strong><p>More instruments can mean more science — or too much power draw and a data queue you cannot return.</p></div><button class="btn primary" data-view="review">Review & simulate ${icon('arrow')}</button></div>`;}
function review(){const a=evaluate(state.design),cacheKey=JSON.stringify(a.d);if(forecastCache?.key!==cacheKey)forecastCache={key:cacheKey,value:forecast(a.d)};const f=forecastCache.value;return `<div class="heading"><div><div class="eyebrow">02 / PRE-FLIGHT REVIEW</div><h1>Ready for the unknown?</h1><p>${esc(a.d.name)} · Validate the design, then take the flight director’s seat.</p></div><button class="btn" data-view="design">← Back to design</button></div><div class="review-grid"><section class="panel"><div class="panel-head"><h2>Design readiness</h2><span class="live-pill" style="color:var(--green)">${a.valid?'FEASIBLE':'HOLD LAUNCH'}</span></div><div class="panel-body">${a.issues.length?a.issues.map(x=>`<div class="issue ${x.level}"><strong>${x.level==='error'?'×':'△'} ${x.title}</strong><p>${x.detail}</p></div>`).join(''):'<div class="issue good"><strong>✓ All nominal checks passed</strong><p>Your design meets budget, mass, objective, power, battery and maneuver requirements. Operations decisions still affect the result.</p></div>'}<div class="notice good"><strong>What happens after launch?</strong><br>Operate 12 blocks. Choose how to divide science collection and transmission. Respond to four events, return the target science, and complete the terminal maneuver.</div></div></section><section class="panel"><div class="panel-head"><h2>Design rehearsal</h2><span class="sectionlabel">32 SEEDED RUNS</span></div><div class="panel-body">${f?`<span class="sectionlabel">BASELINE STRATEGY COMPLETIONS</span><div class="big-number">${f.successes}<span> / ${f.runs} runs</span></div><p class="subnote">${f.min}–${f.max} science points returned across modeled observing conditions. Target: ${a.m.target}. Baseline responds conservatively and uses balanced operations.</p><div class="notice">These are gameplay rehearsals, not a real-world reliability estimate. All runs use the same event sequence with different observing conditions.</div>`:'<div class="notice">Resolve launch blockers to unlock the design rehearsal.</div>'}<table class="table"><tbody>${[['Total planned cost','$'+fmt(a.cost,1)+'M'],['Uncommitted reserve','$'+fmt(a.reserve,1)+'M'],['Dry / wet mass',fmt(a.dry)+' / '+fmt(a.wet)+' kg'],['Available / required Δv',fmt(a.dv)+' / '+fmt(a.requiredDV)+' m/s'],['Mean generation / load',fmt(a.averageGeneration)+' / '+fmt(a.load)+' W'],['Operations duration',a.m.turns*a.m.days+' days']].map(([k,v])=>`<tr><td>${k}</td><td>${v}</td></tr>`).join('')}</tbody></table><div class="actions"><button class="btn primary" data-action="launch" ${!a.valid?'disabled':''}>${icon('arrow')} Launch mission</button><button class="btn" data-action="science">How the model works</button></div><p class="subnote">Launch and transfer are summarized. You begin at the destination after a modeled insertion burn.</p></div></section></div><div class="science-strip"><div><strong>Design is a hypothesis. Operations is the test.</strong><p>Save this blueprint, fly it, and use the debrief to improve your next mission.</p></div><button class="btn" data-action="export">${icon('download')} Save blueprint</button></div>`;}
function chart(s){const a=evaluate(s.design),coords=s.history.map(h=>[30+h.turn/12*450,125-clamp(h.science/a.m.target,0,1.25)*80]),science=[[30,125],...coords].map(x=>x.join(',')).join(' '),queue=[[30,125],...s.history.map(h=>[30+h.turn/12*450,125-clamp(h.queue/100,0,1.25)*80])].map(x=>x.join(',')).join(' ');return `<svg class="chart" viewBox="0 0 500 155" role="img" aria-label="Science returned over ${s.turn} operations blocks: ${fmt(s.science)} points; queued data: ${fmt(s.queue.reduce((x,q)=>x+q.data,0),1)} Mbit"><path d="M30 20v105h450M30 85h450M30 45h450" stroke="#d7dfd2" stroke-width=".7" fill="none"/><path d="M30 45h450" stroke="#829374" stroke-dasharray="3 4"/><text x="34" y="38" font-size="9" fill="#7c8c73" font-family="monospace">SCIENCE TARGET ${a.m.target}</text><polyline points="${science}" fill="none" stroke="#214d45" stroke-width="2.5"/><polyline points="${queue}" fill="none" stroke="#bd8a43" stroke-width="1.5"/>${[0,3,6,9,12].map(n=>`<text x="${30+n/12*450}" y="144" text-anchor="middle" font-size="9" fill="#687574" font-family="monospace">${n}</text>`).join('')}</svg><div class="legend"><span><i></i>Science / target</span><span><i class="orange"></i>Queue / 100 Mbit</span></div>`;}
function log(s){return [...s.log].reverse().map(l=>`<div class="log-entry"><small>BLOCK ${String(l.turn).padStart(2,'0')}</small><strong>${esc(l.title)}</strong><p>${esc(l.detail)}</p></div>`).join('');}
function operations(){const s=state.run;if(!s)return design();const a=evaluate(s.design),key=eventFor(s),event=key&&EVENTS[key],queue=s.queue.reduce((v,q)=>v+q.data,0),ended=s.phase==='complete';return `<div class="heading"><div><div class="eyebrow">03 / MISSION OPERATIONS</div><h1>${esc(s.design.name)}</h1><p>${a.m.body} orbit · ${ended?'Operations complete':`Block ${s.turn+1} of ${a.m.turns}`} · ${a.m.days} days per block</p></div><button class="btn" data-action="export">${icon('download')} Blueprint</button></div><div class="op-stats">${[['SCIENCE RETURNED',fmt(s.science)+' / '+a.m.target,'Only downlinked science counts'],['SPACECRAFT HEALTH',fmt(s.health)+'%','Keep health above 30%'],['PROPELLANT LEFT',fmt(s.fuel,1)+' kg',fmt(deltaV(a.dry,s.fuel,a.e.isp))+' m/s remaining'],['CONTINGENCY', '$'+fmt(s.reserve,1)+'M','For ground response operations']].map(([k,v,n])=>`<div class="mini-stat"><span class="sectionlabel">${k}</span><strong>${v}</strong><small>${n}</small></div>`).join('')}</div><div class="op-grid"><section>${orbit(a,true)}<div class="timeline" aria-label="${s.turn} of 12 blocks complete">${Array.from({length:12},(_,i)=>`<span class="${i<s.turn?'done':i===s.turn?'current':''}"></span>`).join('')}</div>${ended?`<div class="notice good">The mission has ended. Open the debrief to see the result and lessons.</div><button class="btn primary" data-view="debrief">Read mission debrief ${icon('arrow')}</button>`:`<div class="config-header"><h2>Command the next block</h2><span class="sectionlabel">CHOOSE AN OPERATING MODE</span></div><div class="mode-grid">${[['balanced','Balanced','Collect and transmit at nominal rates.'],['observe','Observe','Up to 1.25× collection, capped at 100% duty; 45% downlink.'],['transmit','Transmit','No new collection; 2× downlink.'],['safe','Safe mode','Pause science; 25% downlink.']].map(([id,name,note])=>`<button class="component ${mode===id?'selected':''}" data-mode="${id}" aria-pressed="${mode===id}"><div class="component-top"><strong>${name}</strong><span class="check" aria-hidden="true">${mode===id?'✓':''}</span></div><p>${note}</p></button>`).join('')}</div>${event?`<section class="event-card"><div class="eyebrow">MISSION EVENT / RESPONSE REQUIRED</div><h3>${event.title}</h3><p>${event.text}</p><div class="event-choices">${event.choices.map(x=>{const cost=choiceCost(key,x.id);return `<button class="component ${choice===x.id?'selected':''}" data-choice="${x.id}" aria-pressed="${choice===x.id}" ${cost>s.reserve?'disabled':''}><div class="component-top"><strong>${x.label}</strong><span class="check" aria-hidden="true">${choice===x.id?'✓':''}</span></div><p>${x.note}${cost>s.reserve?' Insufficient reserve.':''}</p></button>`;}).join('')}</div><p style="font-size:10px;margin:12px 0 0">${event.lesson}</p></section>`:''}<div class="op-command"><small>${fmt(queue,1)} Mbit waiting for downlink.<br>${fmt(s.battery)} / ${fmt(a.b.battery*.8)} Wh usable battery charge.</small><button class="btn primary" data-action="advance" ${event&&!choice?'disabled':''}>Execute block ${String(s.turn+1).padStart(2,'0')} ${icon('arrow')}</button></div>`}</section><aside class="op-side"><section class="panel" style="margin-bottom:17px"><div class="panel-head"><h2>Science & data return</h2></div><div class="panel-body">${chart(s)}<p class="subnote">More observations are not always better. A queue that remains at mission end earns no returned-science credit.</p></div></section><section class="panel"><div class="panel-head"><h2>Flight director’s log</h2><span class="sectionlabel">${s.log.length} ENTRIES</span></div><div class="panel-body log">${log(s)}</div></section></aside></div><div style="height:25px"></div>`;}
function choiceCost(key,id){return key==='radiation'&&id==='shield'?3:key==='pointing'&&id==='calibrate'?2:key==='navigation'&&id==='model'?4:0;}
function lessons(s){const a=evaluate(s.design),out=[];if(s.science<a.m.target)out.push('Returned science missed the objective. Improve useful instruments, latitude coverage or science duty, then check that the link can carry the data.');else out.push('Your payload and operations returned enough science to meet the mission objective. Compare a leaner design to see whether you can achieve the same result at lower cost.');if(s.queue.length)out.push(`${fmt(s.queue.reduce((v,q)=>v+q.data,0),1)} Mbit remained onboard. A stronger antenna or a transmit-only block near mission end could recover this value.`);if(!s.retired)out.push('The terminal maneuver could not be completed. Increase propellant margin or choose a more efficient engine before the next flight.');else out.push('You retained enough maneuver capability for final corrections and retirement. That reserve is part of responsible mission design.');if(s.health<80)out.push('Your spacecraft took substantial damage. Conservative event responses and sufficient contingency funds help protect future science return.');if(s.history.some(h=>h.battery===0))out.push('Load shedding drained the modeled battery. Additional power margin or a lower observing duty cycle can improve endurance.');return out;}
function debrief(){const s=state.run;if(!s||s.phase!=='complete')return operations();const a=evaluate(s.design),r=result(s);return `<div class="heading"><div><div class="eyebrow">04 / MISSION DEBRIEF</div><h1>Every flight teaches something.</h1><p>${esc(s.design.name)} · ${a.m.body} orbit · ${s.turn} operations blocks</p></div><button class="btn" data-action="report">${icon('download')} Flight report</button></div><div class="review-grid"><section class="score-card"><span class="eyebrow">${r.success?'OBJECTIVE ACHIEVED':'DESIGN ITERATION REQUIRED'}</span><h2>${r.title}</h2><div class="big-number">${r.score}<span> / 1000</span></div><p>${r.success?'You met the science target, preserved spacecraft health, and completed the terminal maneuver.':'Review the evidence below. A mission can return useful science while falling short of its full objective.'}</p><p>Score: science 650 · health 150 · budget efficiency 100 · retirement 100. Scores are local gameplay feedback.</p><div class="actions"><button class="btn light" data-action="iterate">Refine this design ${icon('arrow')}</button><button class="btn" style="color:white;border-color:#719582" data-action="archive">Compare flights</button></div></section><section class="panel"><div class="panel-head"><h2>What your decisions changed</h2></div><div class="panel-body"><ul class="debrief-lessons">${lessons(s).map(x=>`<li>${x}</li>`).join('')}</ul>${chart(s)}</div></section></div><div class="score-details">${[['SCIENCE RETURNED',fmt(s.science)+' pts',a.m.target+' point objective'],['DATA LEFT ONBOARD',fmt(s.queue.reduce((x,q)=>x+q.data,0),1)+' Mb','Unreturned science earns no credit'],['FINAL HEALTH',fmt(s.health)+'%','Threshold: above 30%'],['TERMINAL MANEUVER',s.retired?'Complete':'Incomplete','Corrections and retirement']].map(([k,v,n])=>`<div class="mini-stat"><span class="sectionlabel">${k}</span><strong>${v}</strong><small>${n}</small></div>`).join('')}</div><section class="panel" style="margin-bottom:25px"><div class="panel-head"><h2>Flight record</h2><span class="sectionlabel">SEED ${a.d.seed}</span></div><div class="panel-body log">${log(s)}</div></section>`;}
function archive(){return `<div class="heading"><div><div class="eyebrow">LOCAL MISSION ARCHIVE</div><h1>A better mission, every time.</h1><p>Compare your last 12 completed flights. These records stay in this browser.</p></div><button class="btn" data-view="design">← Mission design</button></div>${state.archive.length?`<div class="panel" style="margin-bottom:25px"><table class="table"><thead><tr><th>MISSION</th><th>SCIENCE</th><th>SCORE</th><th>OUTCOME</th><th>BLUEPRINT</th></tr></thead><tbody>${state.archive.map((x,i)=>`<tr><td><strong>${esc(x.name)}</strong><br><span class="subnote">${MISSIONS[x.mission].body} · seed ${x.design.seed}</span></td><td>${fmt(x.science)}</td><td>${x.score}</td><td>${x.success?'✓ Achieved':'△ Iterate'}</td><td><button class="btn" data-load="${i}">Refine</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty" style="margin-bottom:30px"><div class="eyebrow">NO FLIGHTS YET</div><h2>Your first mission belongs here.</h2><p>Launch a blueprint and complete its 12 operations blocks.</p><button class="btn primary" data-view="design">Start designing ${icon('arrow')}</button></div>`}`;}
function render(){state.design=normalize(state.design);$('#app').innerHTML=`<div class="shell">${top()}${!storageOK?'<div class="storage-warning">Automatic saving is unavailable. Export blueprints and reports to keep your work.</div>':''}<main id="main">${view==='design'?design():view==='review'?review():view==='operations'?operations():view==='debrief'?debrief():archive()}</main>${footer()}</div>`;save();}
function openDialog(title,body){const d=$('#dialog');d.innerHTML=`<div class="dialog-head"><h2>${title}</h2><button class="iconbtn" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><div class="dialog-body">${body}</div>`;if(!d.open)d.showModal();}
function guide(){openDialog('Welcome to mission control.',`<div class="eyebrow">A 5-MINUTE FLIGHT DIRECTOR’S HANDBOOK</div><p>Start with Earthwatch’s feasible blueprint. Change one component and watch the engineering margins respond.</p>${[['Design with an objective','Choose a destination, select a bus and payload, and configure power, communications and fuel. The mission’s required instruments are marked.'],['Ask the engineering questions','Can the launcher deliver the wet mass? Is average power positive? Can the battery bridge an eclipse? Does the fuel cover insertion and retirement?'],['Run a design rehearsal','Review blockers and advisory flags. The 32-run rehearsal checks your design using a consistent baseline strategy.'],['Operate through the unexpected','Execute one block at a time. Balanced collects and returns data. Observe collects more but transmits less. Transmit clears the queue. Events need your response.'],['Learn, iterate, compare','Return the science target, keep health above 30%, and retain fuel for the terminal maneuver. Read the debrief, refine your blueprint, and compare flights.']].map(([t,p],i)=>`<div class="tutorial-step"><strong>0${i+1}</strong><div><h3>${t}</h3><p>${p}</p></div></div>`).join('')}<div class="notice">This is an educational systems-design game. It does not predict the performance or safety of a real spacecraft.</div><div class="actions"><button class="btn primary" data-action="close">Take the controls ${icon('arrow')}</button><button class="btn" data-action="science">Explore the science</button></div>`);}
const sources=[['NASA · Basics of Space Flight: orbital mechanics','https://science.nasa.gov/learn/basics-of-space-flight/chapter3-4/'],['NASA Glenn · Ideal rocket equation','https://www1.grc.nasa.gov/beginners-guide-to-aeronautics/ideal-rocket-equation/'],['NASA Glenn · Specific impulse','https://www1.grc.nasa.gov/beginners-guide-to-aeronautics/specific-impulse/'],['NASA · Onboard systems: power','https://science.nasa.gov/learn/basics-of-space-flight/chapter11-3/'],['NASA · Small spacecraft power systems','https://www.nasa.gov/smallsat-institute/sst-soa/power-subsystems/'],['NASA · Basics of Space Flight: navigation','https://science.nasa.gov/learn/basics-of-space-flight/chapter13-1/']];
function science(){openDialog('The science behind the trade-offs.',`<h3>Orbital period</h3><div class="formula">T = 2π √((R + h)³ / μ)</div><p>A circular, two-body orbit. Radius and altitude are in km; μ is in km³/s². The displayed period is in minutes. Perturbations, terrain and atmospheric drag are not propagated.</p><h3>Fuel and maneuvers</h3><div class="formula">Δv = Isp × g₀ × ln(mwet / mdry)</div><p>The ideal rocket equation couples propellant, dry mass and engine efficiency. The launcher supplies initial injection. Planetary insertion and reserved corrections / terminal maneuvers are charged to the spacecraft. Tank mass is included in the fixed propulsion package; detailed tank sizing is abstracted.</p><h3>Power and eclipse</h3><div class="formula">Psolar = P1AU / distanceAU²<br>Paverage = Psolar × (1 − eclipse fraction)</div><p>The array rating is its sunlight output at 1 AU. Average load includes housekeeping, duty-weighted instruments and contact-weighted communications. A separate eclipse-energy check uses orbital period and an 80% usable battery capacity. The simulation tracks mean energy per block and sheds load under shortfalls.</p><h3>Science and communications</h3><p>Instrument science yield, data volume, downlink rate, costs, launch capacities, eclipse fractions, health and events are explicit game assumptions. Mapping benefit varies with √(reference altitude / altitude), capped between 0.65 and 1.35, and with a latitude-coverage heuristic. A FIFO queue keeps collected data until transmitted. Only returned science scores.</p><h3>Boundaries of the model</h3><p>Communication rates are fictional net data per block at the mission’s nominal contact fraction. No RF link budget or real ground-station schedule is solved. Transfer geometry, launch windows, thrust duration, radiation dosimetry and detailed thermal control are abstracted. Mission retirement is a simplified budgeted terminal maneuver. The rehearsal is not a reliability prediction.</p><h3>Primary references</h3><ul class="source-list">${sources.map(([n,url])=>`<li><a href="${url}" target="_blank" rel="noopener noreferrer">${n} ↗</a></li>`).join('')}</ul><p>APOGEE is independent and is not endorsed by NASA. No NASA insignia are used.</p>`);}
function brief(){const a=evaluate(state.design);openDialog(a.m.name+' / Mission brief',`<span class="eyebrow">${a.m.tag}</span><h3>${a.m.objective}</h3><p>${a.m.brief}</p><div class="notice good"><strong>Workshop challenge</strong><br>After your first successful flight, design a mission under $${a.m.id==='earth'?55:a.m.id==='moon'?120:125}M that still achieves its science objective. Compare the flight scores in your archive.</div><table class="table"><tbody><tr><td>Budget cap</td><td>$${a.m.budget}M</td></tr><tr><td>Required returned science</td><td>${a.m.target} points</td></tr><tr><td>Operations</td><td>${a.m.turns} × ${a.m.days} days</td></tr><tr><td>Required payload</td><td>${a.m.required.map(x=>INSTRUMENTS.find(i=>i.id===x).name).join('<br>')}</td></tr><tr><td>Solar distance assumption</td><td>${a.m.au} AU</td></tr></tbody></table><p>${a.m.inspiration}</p><div class="notice">Success requires the science target, health above 30%, and a completed terminal maneuver. The mission constants are simplified educational assumptions.</div><button class="btn primary" data-action="close">Start the design</button>`);}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function exportBlueprint(){const d=['operations','debrief'].includes(view)&&state.run?state.run.design:state.design;download(`apogee-${d.mission}-blueprint.json`,JSON.stringify({app:'APOGEE',version:VERSION,design:d},null,2),'application/json');toast('Blueprint exported. Import it on another device to replay.');}
function report(){if(!state.run)return;const s=state.run,a=evaluate(s.design),r=result(s);download(`apogee-${a.m.id}-flight-report.md`,`# APOGEE Flight Report\n\nMission: ${s.design.name}\nDestination: ${a.m.body}\nSeed: ${s.seed}\nOutcome: ${r.title}\nScore: ${r.score}/1000\nScience returned: ${s.science.toFixed(1)}/${a.m.target}\nHealth: ${s.health.toFixed(1)}%\nTerminal maneuver: ${s.retired?'completed':'incomplete'}\n\n## Lessons\n\n${lessons(s).map(x=>'- '+x).join('\n')}\n\n## Operations log\n\n${s.log.map(x=>`### Block ${x.turn}: ${x.title}\n${x.detail}\n`).join('\n')}\n\n## Blueprint\n\n\x60\x60\x60json\n${JSON.stringify(s.design,null,2)}\n\x60\x60\x60\n\n## Model references\n\n${sources.map(([n,u])=>`- [${n}](${u})`).join('\n')}\n\nEducational simulation: costs, hardware, events and science points are fictional. Not a real mission performance prediction.\n`,'text/markdown');toast('Flight report exported.');}
function doLaunch(){state.run=start(state.design);mode='balanced';choice=null;view='operations';$('#dialog').close();render();window.scrollTo({top:0,behavior:'smooth'});toast('Launch and insertion complete. You have the controls.');}
function addArchive(){const s=state.run,r=result(s);state.archive.unshift({name:s.design.name,mission:s.design.mission,design:s.design,science:s.science,score:r.score,success:r.success});state.archive=state.archive.slice(0,12);}
$('#app').addEventListener('click',handleClick);$('#dialog').addEventListener('click',handleClick);
function handleClick(e){const b=e.target.closest('button');if(!b||b.disabled)return;try{if(b.dataset.view){view=b.dataset.view;render();window.scrollTo({top:0,behavior:'smooth'});return;}if(b.dataset.tab){tab=b.dataset.tab;render();return;}if(b.dataset.mission){state.design=preset(b.dataset.mission);forecastCache=null;render();toast('Loaded '+MISSIONS[b.dataset.mission].name+' starter blueprint.');return;}if(b.dataset.component){state.design[b.dataset.kind]=b.dataset.component;render();return;}if(b.dataset.payload){const id=b.dataset.payload;state.design.payload=state.design.payload.includes(id)?state.design.payload.filter(x=>x!==id):[...state.design.payload,id];render();return;}if(b.dataset.mode){mode=b.dataset.mode;render();return;}if(b.dataset.choice){choice=b.dataset.choice;render();return;}if(b.dataset.load!==undefined){state.design=normalize(state.archive[Number(b.dataset.load)].design);view='design';render();return;}
 switch(b.dataset.action){case 'guide':guide();break;case 'brief':brief();break;case 'science':science();break;case 'close':$('#dialog').close();break;case 'export':exportBlueprint();break;case 'report':report();break;case 'archive':view='archive';render();break;case 'iterate':state.design=normalize(state.run.design);view='design';render();window.scrollTo({top:0,behavior:'smooth'});break;case 'launch':if(state.run?.phase==='operations')openDialog('Replace the current flight?',`<p>A mission is still in progress. Launching this blueprint will replace its operations record. Your completed flights stay in the archive.</p><div class="actions"><button class="btn primary" data-action="confirmLaunch">Launch new mission</button><button class="btn" data-action="close">Keep current flight</button></div>`);else doLaunch();break;case 'confirmLaunch':doLaunch();break;case 'advance':{const previous=state.run;state.run=advance(previous,mode,choice);choice=null;if(state.run.phase==='complete'){addArchive();view='debrief';window.scrollTo({top:0,behavior:'smooth'});}render();toast(state.run.phase==='complete'?'Mission complete. Your flight is archived.':`Block ${state.run.turn} executed. Telemetry updated.`);break;}case 'import':importBlueprint();break;}
 }catch(error){toast(error.message||'The command could not be completed.');}}
$('#app').addEventListener('input',e=>{const x=e.target;if(x.dataset.field){state.design[x.dataset.field]=Number(x.value);const label=document.querySelector(`label[for="${x.id}"] strong`);if(label)label.textContent=fmt(Number(x.value))+(x.id==='duty'?'%':x.id==='incl'?'°':x.id==='fuel'?' kg':' km');x.setAttribute('aria-valuetext',label?.textContent||x.value);}if(x.dataset.text){state.design[x.dataset.text]=x.value;save();}});
$('#app').addEventListener('change',e=>{const x=e.target;if(x.dataset.field){state.design[x.dataset.field]=Number(x.value);render();}if(x.dataset.number){state.design[x.dataset.number]=Number(x.value);render();}});
function importBlueprint(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.addEventListener('change',async()=>{const file=input.files?.[0];if(!file)return;try{if(file.size>200000)throw Error('Blueprint is too large. Choose an APOGEE JSON file below 200 KB.');const raw=JSON.parse(await file.text());if(raw.app!=='APOGEE'||raw.version!==VERSION)throw Error('This is not a supported APOGEE blueprint.');state.design=normalize(raw.design);view='design';render();toast('Blueprint imported. Review the design before launch.');}catch(err){toast(err.message||'Could not read the blueprint.');}});input.click();}
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=$('#dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#dialog').close();}});
render();if(!state.visited){state.visited=true;save();setTimeout(guide,200);}
if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
